r"""
For detailed description of the QUTS APIs, please refer to QUTS documentation
    at "C:\Program Files (x86)\Qualcomm\QUTS\QUTS_User_Guide.docm"
This sample includes connecting to device, using Diag, sending commands and collecting logs.

Help:
-t  the time for catch QXDMlogs
-p  to add port which need catch log, [MDM, MSM] for one UE, if mutli UE in one PC, can use [COM3, COM4 ,COM5 ....]
-c  the config for log catch
-s  the saved qxdm logpath and name

Sample usage:
EX in CMD winodws use:
python QXDM5Logcatch.py -t 10 -p MDM -c C:\Users\nokia5G\Desktop\QXDM99\power5gnr01.dmc
                        -s C:\Users\nokia5G\Desktop\QXDM99\test.hdf

EX in Cygwin use:
python QXDM5Logcatch.py -t 10 -p MDM -c C:\\Users\\nokia5G\\Desktop\\QXDM99\\power5gnr01.dmc
                        -s C:\\Users\\nokia5G\\Desktop\\QXDM99\\test.hdf

covert to txt can also use command as below:
C:\Program Files (x86)\Qualcomm\QCAT 6.x\Bin\QCAT.exe -txt C:\Users\nokia5G\Desktop\QXDM99\test.hdf
"""

import os
import sys
import time
import shutil
import argparse


def import_qxdm_libs():
    # WA for PEP8
    sys.path.append(r'C:\Program Files (x86)\Qualcomm\QUTS\Support\python')
    global QutsClient
    global Common
    global DiagService

    import QutsClient
    import Common.ttypes
    import DiagService.DiagService
    import DiagService.constants
    import DiagService.ttypes


import_qxdm_libs()


def collect_qxdm_logs(config, duration, output, port, chip_name):
    qxdm_lc = QXDMLogCollector(config=config, duration=duration, log_file_path=output, port=port, chip_name=chip_name)
    qxdm_lc.remove_output_file()
    qxdm_lc.print_available_devices()
    qxdm_lc.connect_to_device()

    time.sleep(3)

    qxdm_lc.load_config()
    qxdm_lc.capture_log()
    qxdm_lc.save_hdf_log()
    qxdm_lc.cleanup_session()



class QXDMLogCollector(object):
    def __init__(self, config, duration, log_file_path, port, chip_name=None):
        self.config = config
        self.duration = duration
        self.log_file_path = log_file_path
        self.log_dir = os.path.dirname(log_file_path)
        self.port = port
        self.chip_name = chip_name

        self.quts_client = None
        self.dev_manager = None
        self.devices = None
        self.diag_service = None
        self._initcialize_and_get_devices()

    def _initcialize_and_get_devices(self, tries=3):
        attempt = 1
        while not self.devices and attempt <= tries:
            print("ATTEMP: {}".format(attempt))
            self._destroy_quts_client()
            self.quts_client = self._get_quts_client()
            self.dev_manager = self._get_device_manager()
            self.devices = self._get_device_list()
            attempt = attempt + 1
            time.sleep(1)
        self._set_callbacks()

    def _destroy_quts_client(self):
        if self.dev_manager:
            del self.dev_manager
        if self.quts_client:
            del self.quts_client

    def _get_quts_client(self):
        quts_client = QutsClient.QutsClient("LogSessionLiveSample")

        return quts_client

    def _set_callbacks(self):
        self.quts_client.setOnDataQueueUpdatedCallback(_onDataQueueUpdated)
        self.quts_client.setOnMessageCallback(_onMessage)

    def _get_device_manager(self):
        return self.quts_client.getDeviceManager()

    def _get_device_list(self, tries=3):
        # Get the list of devices connected to the PC that supports Diag.

        devices = self.dev_manager.getDevicesForService(DiagService.constants.DIAG_SERVICE_NAME)

        if not devices:
            print("[WARN] Cannot get list of devices connected to PC")
        return devices

    def print_available_devices(self):
        print("Devices Connected to PC: {}".format(self.devices))

    def _select_proper_port(self):
        ports = self.port.split(",")
        print(f"Defined COMs: {ports} and chip name: {self.chip_name}")
        if len(ports) > 1 and self.chip_name is None:
            print("More than 1 COM ports assigned to UE require chip_name parameter for identification.")
            raise Exception("chipName parameter is required for number COM ports > 1")

        for device in self.devices:
            protocols = self.dev_manager.getProtocolList(device)
            for protocol in protocols:
                for port in ports:
                    print(f"\nVerifying com port:{port}...")
                    if protocol.protocolType == Common.ttypes.ProtocolType.PROT_DIAG and port in protocol.description:
                        selected_protocol = protocol.protocolHandle
                        selected_chip_name = self.dev_manager.getChipName(device, selected_protocol)
                        if self.chip_name is None or self.chip_name in selected_chip_name:
                            return device, selected_protocol, selected_chip_name
                        print("{} is not used for log collection.".format(port))
                    else:
                        print("{} is not used for log collection.".format(port))
        print(f"Defined COMs: {ports} for chip name: {self.chip_name} are not used by UE device")
        raise Exception("Fail to connect port COM")

    def connect_to_device(self):
        device, selected_protocol, selected_chip_name = self._select_proper_port()
        self.diag_service = self._get_diag_service(device)
        self.diag_service.initializeServiceByProtocol(selected_protocol)
        print("Device handle: {}".format(device))
        print("Connect with protocol chip named {}".format(selected_chip_name))

        return device

    def _get_diag_service(self, device):
        return DiagService.DiagService.Client(
            self.quts_client.createService(DiagService.constants.DIAG_SERVICE_NAME, device))

    def load_config(self):
        print("Load the config from " + self.config)
        self.diag_service.setLoggingMask(QutsClient.readFile(self.config), Common.ttypes.LogMaskFormat.DMC_FORMAT)

    def capture_log(self):
        print("Start to catch QXDMlog for " + self.duration + " seconds")
        self.dev_manager.startLogging()
        time.sleep(float(self.duration))

    def save_hdf_log(self):
        outfile = self.dev_manager.saveLogFiles(self.log_dir)
        shutil.move(outfile[0], self.log_file_path)
        print("Saved log to: %s" % self.log_file_path)

    def cleanup_session(self):
        self.diag_service.destroyService()
        print("Exit QUTS...")

    def remove_output_file(self):
        try:
            os.unlink(self.log_file_path)
        except BaseException:
            pass


def _onDataQueueUpdated(queueName, queueSize):
    print(queueName, " update ", queueSize)


def _onMessage(level, location, title, description):
    print("Message Received " + title + " " + description)


if __name__ == "__main__":
    arg_parser = argparse.ArgumentParser(description='Parameters: Collect QXDM hdf log')
    arg_parser.add_argument('-t', '--time', dest='time', type=str, required=True, help='time for collecting logs')
    arg_parser.add_argument('-p', '--port', dest='port', type=str, required=True, help='COM port number e.g COM3. In case more then one COM port assigned to UE join it by "," e.g. "COM2,COM5"')
    arg_parser.add_argument('-c', '--config', dest='config', type=str, required=True, help='DMC config file')
    arg_parser.add_argument('-s', '--saveFile', dest='output_file', type=str, required=True, help='Path to log file')
    arg_parser.add_argument('-cn', '--chipName', dest='chip_name', type=str, required=False, help='UE chip name e.g. SDX55M is reqruire in case at least 2 COM ports assigned to UE. Default is string "None"')

    param = arg_parser.parse_args()
    collect_qxdm_logs(config=param.config,
                      duration=param.time,
                      output=param.output_file,
                      port=param.port,
                      chip_name=param.chip_name)
